tape( 'the function performs the rank 1 operation `A = α*x*y^T + A` (row-major)', function test( t ) {
	var expected;
	var alpha;
	var data;
	var out;
	var a;
	var x;
	var y;

	data = rm;

	a = new Complex64Array( data.A );
	x = new Complex64Array( data.x );
	y = new Complex64Array( data.y );

	alpha = new Complex64( data.alpha[0], data.alpha[1] );

	expected = new Complex64Array( data.A_out );

	out = cgeru( data.order, data.M, data.N, alpha, x, data.strideX, y, data.strideY, a, data.lda );
	t.strictEqual( out, a, 'returns expected value' );
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

